async function seedDatabase() {
  await mongoose.connect(process.env.MONGODB_URI || 'mongodb://127.0.0.1:27017/travelenfield');
  await Promise.all([Destination.deleteMany({}),Trip.deleteMany({}),Category.deleteMany({}),Blog.deleteMany({}),Page.deleteMany({}),Hotel.deleteMany({})]);
  await Promise.all([Destination.insertMany(destinations),Trip.insertMany(trips),Category.insertMany(categoryData),Blog.insertMany(blogs),Page.insertMany(pageData),Hotel.insertMany(hotels)]);
  console.log(`Seeded ${destinations.length} destinations, ${trips.length} trips, ${categoryData.length} categories, ${blogs.length} blogs, ${pageData.length} pages and ${hotels.length} hotels.`);
  await mongoose.disconnect();
}

const invokedDirectly = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
if (invokedDirectly) seedDatabase().catch(error => {
  console.error('Database seed failed:', error);
  process.exitCode = 1;
});
